// Note: plain `Omit<Question, 'created_at'>` is NOT used here because Omit does
// not distribute over a discriminated union (keyof Question collapses to only
// the keys common to every branch), which silently drops branch-specific
// fields like `expected_answer`. Omitting 'created_at' from each branch
// individually preserves the discriminated union so short_answer/long_form/
// multiple_choice items are still checked against their own shape.
